// synth: library theory (phase 0)
// doc: Represents the result of Python's strict-greater-than comparison used by max.
// PyGtValue contains the truth value after Python's rich-comparison and truth-testing
// protocols. PyGtRaised contains any propagated exception, including TypeError when
// comparison is unsupported or an exception raised by comparison or truth-testing code.
datatype PyGtResult<E> =
  PyGtValue(value: bool)
| PyGtRaised(exception: E)

// doc: Represents Python max(iterable). PyMaxValue contains the selected element.
// PyMaxEmpty represents ValueError raised when the iterable is empty. PyMaxRaised
// contains an exception propagated unchanged from an element comparison.
datatype PyMaxResult<T, E> =
  PyMaxValue(value: T)
| PyMaxEmpty
| PyMaxRaised(exception: E)

// doc: Processes remaining elements in iteration order, comparing each candidate to
// the current best with Python's strict-greater-than operation. A candidate replaces
// the best only when comparison is true, so the first encountered maximal element is
// retained on ties. Any comparison exception is propagated immediately.
function PythonMaxFrom<T, E>(
    items: seq<T>,
    best: T,
    gt: (T, T) -> PyGtResult<E>
): PyMaxResult<T, E>
  decreases |items|
{
  if |items| == 0 then
    PyMaxValue(best)
  else
    match gt(items[0], best)
    case PyGtRaised(e) => PyMaxRaised(e)
    case PyGtValue(isGreater) =>
      PythonMaxFrom(items[1..],
        if isGreater then items[0] else best,
        gt)
}

// doc: Models Python's one-argument max(iterable) over the elements yielded in
// iteration order. An empty iterable raises ValueError. Otherwise the first element
// is the initial best, later elements are tested with strict greater-than, the first
// maximal element wins ties, and comparison exceptions are propagated unchanged.
