// doc: Models a Python mutable list by its ordered sequence of elements.
class PyList<T> {
  // doc: Contains the Python list's elements in iteration and indexing order.
  var items: seq<T>

  // doc: Models Python's [] expression: it creates a fresh, empty mutable list and raises no language-level exception.
  constructor ()
    ensures items == []
  {
    items := [];
  }

  // doc: Models list.append(value): it mutates the list by placing value after all existing elements and returns None. It raises no index or value exception.
  method Append(value: T)
    modifies this
    ensures items == old(items) + [value]
  {
    items := items + [value];
  }
}

// doc: Implements the stable insertion step used to reproduce Python's ascending ordering of integers; x is placed before the first strictly greater or equal value, preserving the relative order represented by recursive stable sorting.
function InsertSortedInt(xs: seq<int>, x: int): seq<int>
  decreases |xs|
{
  if |xs| == 0 then [x]
  else if x <= xs[0] then [x] + xs
  else [xs[0]] + InsertSortedInt(xs[1..], x)
}

