abstract module PythonLibrary {
  // doc: Represents int(s, 2): PyIntValue(v) denotes normal completion with integer v;
  // PyIntValueError denotes that Python raises ValueError.
  datatype PyIntBase2Result = PyIntValue(value: int) | PyIntValueError

  // doc: Python int(s, 2) ignores leading and trailing Unicode whitespace, then accepts an
  // optional '+' or '-' and a nonempty base-2 numeral. Digits may be Unicode decimal digits
  // with values 0 or 1. A single underscore may separate digits, and one underscore may
  // immediately follow an optional ASCII "0b" or "0B" prefix. Whitespace elsewhere,
  // missing digits, consecutive or trailing underscores, or any other character causes
  // ValueError. The value is the signed mathematical value; negative zero equals zero.
  function PyIntFromBase2(s: string): PyIntBase2Result

  // doc: Returns the nonnegative integer whose binary digits are the digitwise exclusive-or
  // of the binary expansions of nonnegative x and y. Leading zero digits are omitted.
  function NatBitXor(x: nat, y: nat): nat
    decreases x + y
  {
    if x == 0 && y == 0 then 0
    else 2 * NatBitXor(x / 2, y / 2) + ((x % 2 + y % 2) % 2)
  }

  // doc: Python x ^ y on exact integers performs bitwise exclusive-or using conceptually
  // infinite two's-complement representations. It does not overflow or raise an exception.
  function PyIntBitXor(x: int, y: int): int
  {
    if x >= 0 && y >= 0 then
      NatBitXor(x, y)
    else if x < 0 && y < 0 then
      NatBitXor(-x - 1, -y - 1)
    else if x < 0 then
      -NatBitXor(-x - 1, y) - 1
    else
      -NatBitXor(x, -y - 1) - 1
  }

  // doc: Returns the lowercase base-2 digits of n without a prefix or leading zeros.
  // For n equal to zero, the result is exactly "0".
  function BinaryDigits(n: nat): string
    decreases n
  {
    if n < 2 then
      if n == 0 then ['0'] else ['1']
    else
      BinaryDigits(n / 2) + [(if n % 2 == 0 then '0' else '1')]
  }

  // doc: Python bin(n) returns "0b" followed by the lowercase binary digits when n is
  // nonnegative. For negative n it returns "-0b" followed by the digits of -n.
  // Zero is formatted as "0b0"; exact integer inputs do not cause overflow or exceptions.
  function PyBin(n: int): string
  {
    if n >= 0 then "0b" + BinaryDigits(n)
    else "-0b" + BinaryDigits(-n)
  }

  // doc: Normalizes the start index of a Python slice s[start:] with omitted stop and
  // positive unit step. Negative indices count from the end; indices below the beginning
  // become zero, and indices beyond the end become the string length.
  function PySliceStart(length: nat, start: int): nat
  {
    if start < 0 then
      if -start >= length then 0 else length - (-start)
    else if start >= length then
      length
    else
      start
  }

