// synth: library theory (phase 0)
// doc: Models the Python list, integer, and set operations used by clients of this library.
module PythonLibrary {
  // doc: Python len(xs) for a list returns its exact nonnegative number of elements. For a valid built-in list it raises no type-related exception.
  function ListLength(xs: seq<int>): nat {
    |xs|
  }

  // doc: Python integer unary negation returns the additive inverse with arbitrary precision and cannot overflow or raise an exception for an exact int.
  function IntNegate(x: int): int {
    -x
  }

  // doc: Python set(xs), when xs is a list of exact integers, creates a fresh mutable set containing each distinct integer occurring in xs. Duplicate occurrences are discarded; an empty list produces an empty set. Exact integers are hashable, so TypeError is not raised.
  function SetFromIntList(xs: seq<int>): set<int> {
    set i: int | 0 <= i < |xs| :: xs[i]
  }

  // doc: Python x in s for a built-in set of exact integers returns true exactly when an integer equal to x is present. Hash collisions are resolved by equality, and this operation raises no exception for exact integers.
  function IntSetContains(s: set<int>, x: int): bool {
    x in s
  }

  // doc: A Python list iterator stores the index of the next element and whether exhaustion has already been observed. Once exhausted, it remains exhausted even if the list later grows.
  datatype ListIterator = ListIterator(nextIndex: nat, exhausted: bool)

  // doc: Python iter(xs) on a built-in list creates an independent iterator positioned at index zero and does not access any element or raise an exception.
  function StartListIteration(xs: seq<int>): ListIterator {
    ListIterator(0, false)
  }

  // doc: The result of Python list-iterator advancement is either the current element with the updated iterator, or exhaustion corresponding to StopIteration.
  datatype ListIteratorStep =
    | Yield(value: int, yieldedIterator: ListIterator)
    | Stop(stoppedIterator: ListIterator)

  // doc: Python next on a list iterator reads the list's current contents at its stored index. If that index exists, it yields that element and increments the index; thus appends and deletions before exhaustion can affect iteration. If the index is no longer valid, it marks the iterator exhausted and raises StopIteration, represented here by Stop. An already exhausted iterator always produces Stop.
  function AdvanceListIterator(it: ListIterator, currentContents: seq<int>): ListIteratorStep {
    if it.exhausted then
      Stop(it)
    else if it.nextIndex < |currentContents| then
      Yield(currentContents[it.nextIndex],
            ListIterator(it.nextIndex + 1, false))
    else
      Stop(ListIterator(it.nextIndex, true))
  }
}

