// synth: library theory (phase 0)
// doc: Represents the outcome of indexing a Python list with an integer.
// Valid nonnegative and negative indices produce IndexValue; indices outside
// [-len(xs), len(xs) - 1] raise IndexError, represented by RaisedIndexError.
datatype PyListIndexResult<T> = IndexValue(value: T) | RaisedIndexError

// doc: Python len(xs) for a built-in list returns its exact nonnegative number
// of elements and does not modify the list.
function PyListLen<T>(xs: seq<T>): nat
{
  |xs|
}

// doc: Python list indexing with integer i uses i directly when nonnegative
// and len(xs) + i when negative. It raises IndexError when i < -len(xs) or
// i >= len(xs); this total model represents that exception explicitly.
function PyListIndex<T>(xs: seq<T>, i: int): PyListIndexResult<T>
{
  if 0 <= i < |xs| then
    IndexValue(xs[i])
  else if -|xs| <= i < 0 then
    IndexValue(xs[|xs| + i])
  else
    RaisedIndexError
}

// doc: On normal completion, Python list.append(value) mutates the same list
// object by adding value at its end, preserves all prior elements and their
// order, and returns None. It can raise MemoryError if storage allocation
// fails; this function specifies only the contents after normal completion.
function PyListContentsAfterAppend<T>(xs: seq<T>, value: T): seq<T>
{
  xs + [value]
}

// doc: For an integer stop, Python range(stop) iterates over 0, 1, ..., stop-1
// in ascending order. It is empty when stop <= 0 and excludes stop itself.
function PyRange(stop: int): seq<int>
{
  if stop <= 0 then [] else seq(stop, i => i)
}

