// synth: library theory (phase 0)
// doc: Represents the observable outcomes of evaluating int(n ** 0.5): either
// an integer is returned, int() raises TypeError for a complex result, or the
// floating-point conversion performed by exponentiation raises OverflowError.
datatype PyIntHalfPowerResult =
  ReturnedInt(value: int)
  | RaisedTypeError
  | RaisedOverflowError

// doc: Evaluates Python's int(n ** 0.5) for an integer n. Exponentiation uses
// Python's platform float approximation to 0.5 power. For a nonnegative n that
// can be converted to float, int() truncates the finite result toward zero.
// For a negative n successfully converted for exponentiation, power produces a
// complex value and int() raises TypeError. If converting n for floating-point
// exponentiation is out of range, exponentiation raises OverflowError.
function PyIntAfterHalfPower(n: int): PyIntHalfPowerResult

// doc: Returns Python's integer remainder a % b. The result satisfies
// a == b * floor(a / b) + result, has the sign of b unless it is zero, and has
// absolute value less than |b|. Python raises ZeroDivisionError when b is zero.
function PyIntMod(a: int, b: int): int
  requires b != 0
{
  if b > 0
  then a - b * (a / b)
  else a - b * ((-a) / (-b))
}

// doc: Gives the mathematical number of integers yielded by
// range(start, stop, step). The stop value is excluded. The count is zero when
// the first value already lies at or beyond stop in the direction of step.
// Python raises ValueError when step is zero.
function PyRangeCount(start: int, stop: int, step: int): nat
  requires step != 0
{
  if step > 0 then
    if start >= stop then 0
    else (stop - start + step - 1) / step
  else
    if start <= stop then 0
    else (start - stop + (-step) - 1) / (-step)
}

// doc: Returns, in Python iteration order, the integer values yielded by
// range(start, stop, step): start + k*step for consecutive k beginning at zero,
// while each value remains strictly before stop in step's direction. The stop
// value is excluded. Python raises ValueError when step is zero.
function PyRangeValues(start: int, stop: int, step: int): seq<int>
  requires step != 0
{
  seq(PyRangeCount(start, stop, step), k => start + k * step)
}

