// synth: library theory (phase 0)
// doc: A Python str consists of Unicode code points in the range U+0000 through U+10FFFF, including possible surrogate code points.
type PyCodePoint = cp: int | 0 <= cp < 0x110000 witness 0

// doc: Python str values are immutable finite sequences of Unicode code points; their length is the number of code points.
type PyString = seq<PyCodePoint>

// doc: Reports whether Python's bundled Unicode database classifies the code point as cased. This classification depends on the Unicode database version used by the Python implementation and raises no exception for a valid code point.
predicate UnicodeIsCased(cp: PyCodePoint)

// doc: Reports whether Python's bundled Unicode database classifies the code point as uppercase. This classification depends on the Unicode database version used by the Python implementation and raises no exception for a valid code point.
predicate UnicodeIsUpper(cp: PyCodePoint)

// doc: str.isupper() returns true exactly when the string contains at least one cased character and every cased character is uppercase; uncased characters are ignored. It returns false for the empty string and raises no exception for a str receiver.
function PyStrIsUpper(s: PyString): bool {
  (exists i :: 0 <= i < |s| && UnicodeIsCased(s[i])) &&
  (forall i :: 0 <= i < |s| && UnicodeIsCased(s[i]) ==> UnicodeIsUpper(s[i]))
}

// doc: Iterating over a Python str yields one-character str values from left to right, one per Unicode code point. An empty string yields none; requesting another item after exhaustion raises StopIteration. Strings cannot be mutated during iteration.
function PyStringIteration(s: PyString): seq<PyString>
  decreases |s|
{
  if |s| == 0 then []
