  datatype PyException =
    PyIndexError |
    PyTypeError |
    PyPropagatedException

  // doc: Represents either normal completion with a value or termination by raising the represented Python exception.
  datatype PyResult<T> =
    PyOk(value: T) |
    PyErr(error: PyException)

  // doc: Represents completion of a statement or termination by raising the represented Python exception.
  datatype PyStatus =
    PyCompleted |
    PyRaised(error: PyException)

  // doc: Models a mutable built-in Python list whose elements retain their identities when lists are shallowly copied or sliced.
