    // doc: Contains the list elements in Python index order.
    var elements: seq<T>

    // doc: Constructs a list containing exactly the supplied elements in order.
    constructor (initial: seq<T>)
      ensures elements == initial
    {
      elements := initial;
    }

    // doc: Python len on a built-in list returns its nonnegative number of elements and does not modify the list.
    function Len(): int
      reads this
    {
      |elements|
    }

    // doc: list.copy() creates a distinct list with the same element references in the same order; the copy is shallow and subsequent structural mutations of either list do not mutate the other.
    method Copy() returns (copy: PyList<T>)
      ensures copy != this
      ensures copy.elements == old(elements)
    {
      copy := new PyList(elements);
    }

