// doc: Finds the first occurrence of a nonempty separator at or after start, returning -1 if absent. This is an internal operation and raises no exception.
function FindSeparator(s: string, sep: string, start: nat): int
  requires sep != ""
  requires start <= |s|
  ensures FindSeparator(s, sep, start) == -1 ||
          start <= FindSeparator(s, sep, start) < |s|
  ensures FindSeparator(s, sep, start) >= 0 ==>
          FindSeparator(s, sep, start) + |sep| <= |s|
  decreases |s| - start
{
  if start + |sep| > |s| then
    -1
  else if s[start .. start + |sep|] == sep then
    start
  else
    FindSeparator(s, sep, start + 1)
}

// doc: Produces Python's left-to-right, nonoverlapping split fields from start using a nonempty explicit separator. Empty leading, trailing, and adjacent fields are retained.
function SplitParts(s: string, sep: string, start: nat): seq<string>
  requires sep != ""
  requires start <= |s|
  decreases |s| - start
{
  var p := FindSeparator(s, sep, start);
  if p == -1 then
    [s[start..]]
  else
    [s[start..p]] + SplitParts(s, sep, p + |sep|)
}

