  ensures -1 <= IndexOfStringKey(entries, key, start) < |entries|
  ensures IndexOfStringKey(entries, key, start) >= 0 ==>
          entries[IndexOfStringKey(entries, key, start)].0 == key
  decreases |entries| - start
{
