    -1
  else if entries[start].0 == key then
    start
  else
    IndexOfStringKey(entries, key, start + 1)
}

// doc: Models a mutable Python dict whose keys are strings. Entries retain insertion order; assigning an existing key does not change its position.
class PyStringDict<V> {
  // doc: Stores dictionary key-value pairs in Python insertion order, with each key occurring at most once when modified through this class's operations.
  var entries: seq<(string, V)>

  // doc: Models dict(), creating an empty dictionary.
  constructor ()
    ensures entries == []
  {
    entries := [];
  }

  // doc: Models key in d for a string-keyed dictionary. It returns true exactly when an equal key is present and raises no exception.
  function Contains(key: string): bool
    reads this
