  // doc: Models d[key] = value. A new key is appended to insertion order; an existing key's value is replaced without moving the key. String keys are hashable, so no TypeError is raised.
  method Assign(key: string, value: V)
    modifies this
  {
    var i := IndexOfStringKey(entries, key, 0);
    if i < 0 {
      entries := entries + [(key, value)];
    } else {
      entries := entries[i := (key, value)];
