theory:
// synth: library theory (phase 0)
// doc: Models the Python built-in values and list operations used below.
abstract module PythonLibrary {
  // doc: A Python float is an IEEE-754 binary64 value, including signed zeros,
  // infinities, and NaNs.
  type PyFloat

  // doc: float('inf') returns positive infinity and raises no exception.
  function FloatPositiveInfinity(): PyFloat

  // doc: Python float subtraction uses IEEE-754 binary64 arithmetic with
  // round-to-nearest ties-to-even. It may produce infinities, signed zero, or
  // NaN; subtraction of equal infinities produces NaN and raises no exception.
  function FloatSub(left: PyFloat, right: PyFloat): PyFloat

  // doc: Python's < on exact floats compares their numeric IEEE-754 values.
  // It is false if either operand is NaN; signed zeros compare equal, and
  // infinities compare below or above all finite values as appropriate.
  // Comparing two exact floats raises no exception.
  function FloatLess(left: PyFloat, right: PyFloat): bool

  // doc: Represents either Python's singleton None or a present value.
  datatype PyOptional<T> = PyNone | PySome(value: T)

  // doc: A slice bound is either omitted or an integer accepted as a Python
  // slice index.
  datatype SliceBound = BoundOmitted | BoundAt(index: int)

  // doc: For a positive-step slice of a sequence of length n, an omitted start
  // becomes 0, an omitted stop becomes n, a negative bound is first increased
  // by n, and the result is clamped to the inclusive range 0 through n.
  function NormalizePositiveSliceBound(
      n: nat, bound: SliceBound, isStart: bool): nat
  {
    match bound
    case BoundOmitted => if isStart then 0 else n
    case BoundAt(i) =>
      var shifted := if i < 0 then i + n else i;
      if shifted < 0 then 0
      else if shifted > n then n
      else shifted
  }

  // doc: Python xs[start:stop] with omitted step uses step 1, normalizes and
  // clamps the bounds as specified above, and returns a new shallow list
  // containing indices start through stop-1. If stop is not greater than
  // start, it returns an empty list. Integer slicing never raises IndexError.
  function Slice<T>(
      xs: seq<T>, start: SliceBound, stop: SliceBound): seq<T>
  {
    var lo := NormalizePositiveSliceBound(|xs|, start, true);
    var hi := NormalizePositiveSliceBound(|xs|, stop, false);
    if lo < hi then xs[lo..hi] else []
  }

  // doc: Python zip(left, right) iterates both inputs from left to right and
  // yields pairs until either input is exhausted, discarding no already-yielded
  // pairs and producing no fill values. For lists not mutated during iteration,
  // this sequence is exactly the yielded order.
  function Zip<A, B>(left: seq<A>, right: seq<B>): seq<(A, B)>
  {
    var n := if |left| < |right| then |left| else |right|;
    seq(n, i => (left[i], right[i]))
  }

  // doc: Returns the sequence produced by Python list.sort() on a list
  // containing exact floats. Sorting is in place, stable, uses float <, and
  // returns None. Because NaN makes < non-total, no ordinary total-order
  // guarantee applies to lists containing NaNs; their arrangement follows
  // Python's stable sorting algorithm and can depend on the original order.
  function FloatStableSort(xs: seq<PyFloat>): seq<PyFloat>

  // doc: Models a mutable Python list whose elements are exact floats.
  class PyFloatList {
    // doc: The elements appear in Python list iteration and indexing order.
    var items: seq<PyFloat>

    // doc: Constructing a list from these elements creates a list with the
    // same ordered references; constructing this exact-float list raises no
    // element-related exception.
    constructor (xs: seq<PyFloat>)
      ensures items == xs
    {
      items := xs;
    }

    // doc: Python list.sort() stably rearranges this list in place according
    // to float < and returns None. Exact-float comparisons raise no exception;
    // NaNs make the comparison non-total, so the result need not satisfy a
    // conventional numeric sortedness predicate.
    method Sort()
      modifies this
      ensures items == FloatStableSort(old(items))
    {
      items := FloatStableSort(items);
    }
  }
}

