// synth: library theory (phase 0)
// doc: Represents a Python exception object whose identity is preserved when an operation propagates it.
class PyException {}

// doc: Represents either successful completion with a value or abrupt completion by a Python exception.
datatype PyResult<T> =
  PySuccess(value: T)
| PyFailure(exc: PyException)

// doc: Models a Python list comprehension over a finite sequence. Elements are visited in order.
// doc: The predicate is evaluated first; false skips the expression. Any predicate or expression exception is propagated immediately.
function PyListComprehension<T, U>(
    xs: seq<T>,
    predFn: T -> PyResult<bool>,
    exprFn: T -> PyResult<U>
  ): PyResult<seq<U>>
  decreases |xs|
{
  if |xs| == 0 then
    PySuccess([])
  else
    match predFn(xs[0])
    case PyFailure(exc) => PyFailure(exc)
    case PySuccess(keep) =>
      if !keep then
        PyListComprehension(xs[1..], predFn, exprFn)
      else
        match exprFn(xs[0])
        case PyFailure(exc) => PyFailure(exc)
        case PySuccess(value) =>
          match PyListComprehension(xs[1..], predFn, exprFn)
          case PyFailure(exc) => PyFailure(exc)
          case PySuccess(rest) => PySuccess([value] + rest)
}

