  method Append(value: T)
    modifies this
    ensures items == old(items) + [value]
  {
    items := items + [value];
  }

  // doc: Python list[:-1] creates a fresh shallow list containing indices 0 through len(list)-2. For an empty list the result is empty. The stop value -1 is normalized to max(len(list)-1, 0). Element references are preserved, and allocation may raise MemoryError.
  method SliceToMinusOne() returns (result: PyList<T>)
    ensures result != this
    ensures result.items == (if |items| == 0 then [] else items[..|items| - 1])
  {
    result := new PyList<T>(
      if |items| == 0 then [] else items[..|items| - 1]
    );
  }
}

// doc: A successful Python iterator step yields its next element.
datatype PyIterationResult<T> =
  // doc: Represents the value returned by Python's iterator __next__ operation when an element remains.
  Yield(value: T)
|
