  const owner: PyList<T>

  // doc: The zero-based index that the next successful iterator step will read.
  var index: nat

  // doc: Records whether Python's list iterator has become exhausted; subsequent steps then continue raising StopIteration even if the list later grows.
  var exhausted: bool

  // doc: Python iter(list) creates a fresh iterator positioned before index zero without copying the list.
  constructor (list: PyList<T>)
    ensures owner == list
    ensures index == 0
    ensures !exhausted
  {
    owner := list;
    index := 0;
    exhausted := false;
  }

  // doc: Python next(iterator) returns the element at the iterator's current index and advances the index when that index is below the list's current length. Otherwise it raises StopIteration and permanently exhausts the iterator.
