// doc: Represents the outcome of converting a built-in Python int to decimal
// text. Python raises ValueError when the configured nonzero maximum number of
// decimal digits is exceeded; otherwise it returns the resulting str.
datatype PyIntStringResult =
  PyIntStringValue(value: string)
| PyIntStringValueError

// doc: Returns the ASCII character for an integer from 0 through 9.
function PyDecimalChar(d: int): char
  requires 0 <= d < 10
{
  if d == 0 then '0'
  else if d == 1 then '1'
  else if d == 2 then '2'
  else if d == 3 then '3'
  else if d == 4 then '4'
  else if d == 5 then '5'
  else if d == 6 then '6'
  else if d == 7 then '7'
  else if d == 8 then '8'
  else '9'
}

// doc: Produces the base-10 representation of a nonnegative integer.
function PyUnsignedDecimal(n: int): string
  requires 0 <= n
  decreases n
{
  if n < 10 then
    [PyDecimalChar(n)]
  else
    PyUnsignedDecimal(n / 10) + [PyDecimalChar(n % 10)]
}

// doc: Models str(i) for a built-in Python int.
function PyStrInt(i: int, maxDigits: nat): PyIntStringResult
{
  var digits := if i < 0 then PyUnsignedDecimal(-i) else PyUnsignedDecimal(i);
  if maxDigits != 0 && |digits| > maxDigits then
    PyIntStringValueError
  else if i < 0 then
    PyIntStringValue("-" + digits)
  else
    PyIntStringValue(digits)
}

// doc: Represents Python string integer-indexing.
datatype PyStringIndexResult =
  PyStringElement(value: char)
| PyStringIndexError

// doc: Models s[i] for a Python str and integer i.
function PyStringIndex(s: string, i: int): PyStringIndexResult
{
  var j := if i < 0 then |s| + i else i;
  if 0 <= j < |s| then PyStringElement(s[j]) else PyStringIndexError
}

// doc: Models s[start:] for a Python str and integer start.
function PyStringSliceFrom(s: string, start: int): string
{
  var j :=
    if start < 0 then
      if |s| + start < 0 then 0 else |s| + start
    else
      if start > |s| then |s| else start;
  s[j..]
}

// doc: Reports whether a character is an ASCII decimal digit.
function PyIsAsciiDigit(c: char): bool
{
  c == '0' || c == '1' || c == '2' || c == '3' || c == '4' ||
  c == '5' || c == '6' || c == '7' || c == '8' || c == '9'
}

// doc: Models int(x) for a one-character ASCII decimal digit.
function PyIntAsciiDigit(c: char): int
  requires PyIsAsciiDigit(c)
{
  if c == '0' then 0
  else if c == '1' then 1
  else if c == '2' then 2
  else if c == '3' then 3
  else if c == '4' then 4
  else if c == '5' then 5
  else if c == '6' then 6
  else if c == '7' then 7
  else if c == '8' then 8
  else 9
}

// doc: Models iteration over a Python str.
function PyStringIteration(s: string): seq<char>
{
  s
}

// doc: Adds a sequence of Python integers.
function PySumFrom(values: seq<int>, accumulator: int): int
  decreases |values|
{
  if |values| == 0 then
    accumulator
  else
    PySumFrom(values[1..], accumulator + values[0])
}

// doc: Models sum(values).
function PySum(values: seq<int>): int
{
  PySumFrom(values, 0)
}

// synth: Python interpreter int-to-string digit limit
const PyCurrentMaxDigits: nat

// synth: counterexample fact: one negative element can contribute nine
lemma NegativeNineDigitContribution()
  ensures PyIsAsciiDigit('9')
  ensures PyIntAsciiDigit('9') == 9
  ensures PyIntAsciiDigit('9') > |[-9]|
{
}

// synth: named fact: the supplied upper bound is false for the negative-nine contribution
lemma RequiredUpperBoundCounterexample()
  ensures PyIntAsciiDigit('9') > |[-9]|
{
  NegativeNineDigitContribution();
}

// synth: named fact: int-to-string conversion is not total under an arbitrary nonzero limit
lemma IntStringLimitCounterexample()
  ensures PyStrInt(10, 1) == PyIntStringValueError
{
  assert PyUnsignedDecimal(1) == "1";
  assert PyUnsignedDecimal(10) == "10";
}

// synth: named fact: therefore the frozen value destructor is not universally defined
lemma IntStringResultMayNotHaveValue()
  ensures !PyStrInt(10, 1).PyIntStringValue?
{
  IntStringLimitCounterexample();
}

// synth: named fact: without a digit limit, -9 reaches the failing contribution
lemma NegativeNineExecutionCounterexample()
  ensures PyStrInt(-9, 0) == PyIntStringValue("-9")
  ensures PyStringIndex("-9", 1) == PyStringElement('9')
  ensures PyIntAsciiDigit('9') == 9
  ensures 9 > |[-9]|
{
  assert PyUnsignedDecimal(9) == "9";
  assert "-9"[1] == '9';
  NegativeNineDigitContribution();
}

// synth: named fact: the loop increment itself violates the claimed array bound
lemma NegativeNineLoopIncrementExceedsArrayLength()
  ensures 0 + 9 > |[-9]|
{
}

// synth: named fact: -9 converts successfully for every possible digit limit
lemma NegativeNineConversionForAnyLimit(maxDigits: nat)
  ensures PyStrInt(-9, maxDigits) == PyIntStringValue("-9")
{
  assert PyUnsignedDecimal(9) == "9";
  if maxDigits != 0 {
    assert 1 <= maxDigits;
  }
}

// synth: named fact: the exact negative-nine result cannot satisfy the entry upper bound
lemma NegativeNinePostconditionIsFalse()
  ensures !(0 <= 9 <= |[-9]|)
{
  NegativeNineLoopIncrementExceedsArrayLength();
}

// synth: named fact: the counterexample survives every configured digit limit
lemma NegativeNineDefeatsSpecificationForAnyLimit(maxDigits: nat)
  ensures PyStrInt(-9, maxDigits) == PyIntStringValue("-9")
  ensures !(0 <= 9 <= |[-9]|)
{
  NegativeNineConversionForAnyLimit(maxDigits);
  NegativeNinePostconditionIsFalse();
}

