// synth: library theory (phase 0)
// doc: A Python string element is a Unicode code point from U+0000 through
// doc: U+10FFFF, including surrogate code points. Creating one outside this
// doc: range via chr raises ValueError.
type PyChar = c: int | 0 <= c < 1114112 witness 0

// doc: A Python str is an immutable finite sequence of Unicode code points.
type PyStr = seq<PyChar>

// doc: Returns whether c has Unicode general category Ll, Lm, Lo, Lt, or Lu
// doc: in Python's bundled Unicode database. It raises no exception.
predicate UnicodeLetter(c: PyChar)

// doc: str.isalpha() is true exactly when the string is nonempty and every
// doc: code point is a Unicode letter. It is false for the empty string and
// doc: raises no exception for a str receiver.
function IsAlpha(s: PyStr): bool {
  |s| > 0 &&
  (forall i :: 0 <= i < |s| ==> UnicodeLetter(s[i]))
}

// doc: Iterating over a str yields one-character strings in increasing code
// doc: point-index order. After the final character, iterator advancement
// doc: raises StopIteration; an empty string stops immediately.
function IterCharacters(s: PyStr): seq<PyStr> {
  seq(|s|, i => [s[i]])
}

// doc: str.swapcase() returns the string produced by applying Python's Unicode
// doc: swapcase mapping to every code point in order. Case mappings may expand
// doc: to multiple code points, uncased characters remain unchanged, and the
// doc: operation need not be its own inverse. It has no language-level
// doc: exception for a str receiver, though allocation may raise MemoryError.
function SwapCase(s: PyStr): PyStr

// doc: Concatenating two strings preserves all code points of the left operand
// doc: followed by all code points of the right operand. Strings are immutable,
// doc: so += rebinds rather than mutating the original string. Valid str
// doc: operands cause no type error; allocation may raise MemoryError.
function Concat(a: PyStr, b: PyStr): PyStr {
  a + b
}

// doc: s[::-1] uses a slice step of -1 with omitted bounds and therefore
// doc: returns all code points in reverse order. Empty and one-character
// doc: strings are handled normally; the fixed nonzero step raises no
// doc: ValueError, though allocation may raise MemoryError.
function ReverseSlice(s: PyStr): PyStr {
  seq(|s|, i => s[|s| - 1 - i])
}

