  datatype PyResult<T> =
    Value(value: T) |
    Raised(exception: PyNumericException)

  // doc: Represents a finite value of Python's implementation-defined floating-point type, including signed zero but excluding infinities and NaNs.
  type PyFiniteFloat

  // doc: Returns the exact mathematical real value represented by a finite Python float; positive and negative zero both map to real zero.
  function PyFloatReal(x: PyFiniteFloat): real

  // doc: Python integer true division converts the quotient to the implementation's float format using its prescribed rounding. A zero divisor raises ZeroDivisionError. A finite quotient too large for that format raises OverflowError; underflow instead produces a signed zero or subnormal value.
