theory:
// synth: library theory (phase 0)
// doc: This abstract module models the relevant immutable Python string and sequence operations.
abstract module PythonLibrary {
  // doc: A Python string element is a Unicode code point from U+0000 through U+10FFFF, including surrogate code points.
  type PyCodePoint = c: int | 0 <= c < 1114112 witness 0

  // doc: A Python str is an immutable, ordered sequence of Unicode code points; equality compares equal-length sequences point by point.
  datatype PyString = MkPyString(codePoints: seq<PyCodePoint>)

  // doc: Reports whether a code point is alphabetic according to the Unicode database used by Python: its general category is a Unicode Letter category.
  function UnicodeIsAlphabetic(c: PyCodePoint): bool

  // doc: Reports whether a code point is a digit according to the Unicode database used by Python, including decimal digits and compatible digit characters such as superscript digits.
  function UnicodeIsDigit(c: PyCodePoint): bool

  // doc: Python str.lower() returns the string transformed using the Unicode lowercase algorithm and Python's bundled Unicode database. A character may map to multiple code points, so the length may change. For a str receiver it raises no exception.
  function PyLower(s: PyString): PyString

  // doc: Models str.count(sub) beginning at a specified valid code-point boundary. Matches are selected from left to right without overlap. An empty substring matches at every boundary, including the final boundary.
  function CountFrom(haystack: seq<PyCodePoint>, needle: seq<PyCodePoint>, start: nat): nat
    requires start <= |haystack|
    decreases |haystack| - start
  {
    if |needle| == 0 then
      |haystack| - start + 1
    else if start + |needle| > |haystack| then
      0
    else if haystack[start .. start + |needle|] == needle then
      1 + CountFrom(haystack, needle, start + |needle|)
    else
      CountFrom(haystack, needle, start + 1)
  }

  // doc: Python str.count(sub) returns the number of non-overlapping occurrences of sub. For an empty sub it returns len(s)+1. A non-str argument raises TypeError.
  function PyCount(s: PyString, sub: PyString): nat
  {
    CountFrom(s.codePoints, sub.codePoints, 0)
  }

  // doc: Models the left-to-right substring search used by str.split, returning the least matching index at or after start, or -1 if none exists.
  function FindFrom(haystack: seq<PyCodePoint>, needle: seq<PyCodePoint>, start: nat): int
    requires 0 < |needle|
    requires start <= |haystack|
    ensures FindFrom(haystack, needle, start) == -1 ||
      (start <= FindFrom(haystack, needle, start) &&
       FindFrom(haystack, needle, start) + |needle| <= |haystack|)
    decreases |haystack| - start
  {
    if start + |needle| > |haystack| then
      -1
    else if haystack[start .. start + |needle|] == needle then
      start
    else
      FindFrom(haystack, needle, start + 1)
  }

  // doc: Models explicit-separator str.split from a valid boundary. Every non-overlapping separator is consumed left to right, and empty fields are retained at the beginning, between adjacent separators, and at the end.
  function SplitFrom(haystack: seq<PyCodePoint>, separator: seq<PyCodePoint>, start: nat): seq<PyString>
    requires 0 < |separator|
    requires start <= |haystack|
    decreases |haystack| - start
  {
    var k := FindFrom(haystack, separator, start);
    if k == -1 then
      [MkPyString(haystack[start ..])]
    else
      [MkPyString(haystack[start .. k])] +
      SplitFrom(haystack, separator, k + |separator|)
  }

  // doc: Python str.split(sep) with an explicit nonempty separator splits at every non-overlapping occurrence and preserves empty fields. An empty separator raises ValueError; a non-str separator raises TypeError.
  function PySplit(s: PyString, separator: PyString): seq<PyString>
    requires 0 < |separator.codePoints|
  {
    SplitFrom(s.codePoints, separator.codePoints, 0)
  }

  // doc: Python sequence indexing accepts indices from -len(xs) through len(xs)-1; negative indices are translated by adding len(xs). Other indices raise IndexError. Objects without an integer indexing conversion raise TypeError.
  function PyIndex<T>(xs: seq<T>, index: int): T
    requires -|xs| <= index < |xs|
  {
    xs[if index < 0 then |xs| + index else index]
  }

  // doc: Python str.isalpha() is true exactly when the string is nonempty and every code point is alphabetic according to Python's Unicode database; it is false for the empty string.
  function PyIsAlpha(s: PyString): bool
  {
    0 < |s.codePoints| &&
    forall i :: 0 <= i < |s.codePoints| ==> UnicodeIsAlphabetic(s.codePoints[i])
  }

  // doc: Python str.isdigit() is true exactly when the string is nonempty and every code point is a Unicode digit according to Python's Unicode database; it is false for the empty string.
  function PyIsDigit(s: PyString): bool
  {
    0 < |s.codePoints| &&
    forall i :: 0 <= i < |s.codePoints| ==> UnicodeIsDigit(s.codePoints[i])
  }

  // doc: Iterating over a Python str yields one-character strings in increasing code-point-index order, from the first character to the last; an empty string yields no elements.
  function PyStringCharacters(s: PyString): seq<PyString>
  {
